mapper.insert:
/* 
 * isry.couns.constt.bbsnav.mapper.BbsnavListMapper.insertBbsnav : 기타상담게시판 원글(AYE100) 등록
 * 2023.04.17 수정 : 불필요한 컬럼 삭제 / 필요한 컬럼 추가 - Jeong.Won.Je
 */

   SELECT  AYE100_SQ01.CURRVAL
   FROM    DUAL

    INSERT  
	INTO    
            AYE100 
	(
	        BBSCTT_ESNTAL_NO           /* 게시글번호 */
	    ,   BBSCTT_TYPE_SE_CD          /* 게시글코드 */
	    ,   BBSCTT_TTL_NM              /* 게시글제목 */
	    ,   WRTR_NM_ENCPT              /* 작성자명 */

	    ,   HPGE_URL_ADDR              /* 홈페이지 URL주소 */

	    ,   BBSCTT_CN                  /* 게시글내용 */
	    ,   SXDC_SE_CD                 /* 성별구분코드 */
	    ,   ACBG_SE_CD                 /* 학력구분코드 */
	    ,   GRADE_SE_CD                /* 학년구분코드 */
	    ,   GRDTN_STTS_SE_CD           /* 졸업상태구분코드 */
	    ,   REAL_CONSTT_SE_CD          /* 실제상담자구분코드 */
	    ,   REAL_CONSTT_ETC_CN         /* 실제상담자기타내용 */
	    ,   YNGBGS_SE_NO               /* 청소년구분번호 */
	    ,   PROBM_STTS_LCLAS_SE_CD     /* 문제상태대분류구분코드 */
	    ,   PROBM_STTS_MLSFC_SE_CD     /* 문제상태중분류구분코드 */
	    ,   PROBM_STTS_SCLAS_SE_CD     /* 문제상태소분류구분코드 */
	    ,   PROBM_CAS_LCLAS_SE_CD      /* 문제원인대분류구분코드 */
	    ,   PROBM_CAS_SCLAS_SE_CD      /* 문제원인소분류구분코드 */
	    ,   ETC_CN                     /* 기타내용 */
	    ,   LINK_PRCS_SE_CN            /* 연계처리구분내용 */
	    ,   RCPT_RQST_COURS_SE_CD      /* 접수의뢰경로구분코드 */
	    ,   LINK_INST_NM               /* 연계기관명 */
	    ,   FRST_RGTR_ID
	    ,   FRST_REG_DT
	    ,   LAST_MDFR_ID
	    ,   LAST_MDFCN_DT
	)
	VALUES
	(

	        AYE100_SQ01.NEXTVAL        
	    ,   #{BBSCTT_TYPE_SE_CD}       
	    ,   #{BBSCTT_TTL_NM}
	    ,   C##RG.ENC_B64(#{WRTR_NM_ENCPT})

	    ,   #{HPGE_URL_ADDR}

	    ,   #{BBSCTT_CN}
	    ,   #{SXDC_SE_CD}
	    ,   #{ACBG_SE_CD}
	    ,   #{GRADE_SE_CD}
	    ,   #{GRDTN_STTS_SE_CD}
	    ,   #{REAL_CONSTT_SE_CD}
	    ,   #{REAL_CONSTT_ETC_CN}
	    ,   #{YNGBGS_SE_NO}
	    ,   #{PROBM_STTS_LCLAS_SE_CD}
	    ,   #{PROBM_STTS_MLSFC_SE_CD}
	    ,   #{PROBM_STTS_SCLAS_SE_CD}
	    ,   #{PROBM_CAS_LCLAS_SE_CD}
	    ,   #{PROBM_CAS_SCLAS_SE_CD}
	    ,   #{ETC_CN}
	    ,   #{LINK_PRCS_SE_CN}
	    ,   #{RCPT_RQST_COURS_SE_CD}
	    ,   #{LINK_INST_NM}
	    ,   #{FRST_RGTR_ID}
	    ,   SYSDATE
	    ,   #{LAST_MDFR_ID}
	    ,   SYSDATE 
	)

mapper.update:
/* 
 * isry.couns.constt.bbsnav.mapper.BbsnavListMapper.updateBbsnav : 기타상담게시판 원글(AYE100) 수정
 * 2023.04.17 수정 : 불필요한 컬럼 삭제 / 필요한 컬럼 추가 - Jeong.Won.Je
 */
	UPDATE  
            AYE100  
	SET
	        BBSCTT_TTL_NM               =       #{BBSCTT_TTL_NM}

        ,   HPGE_URL_ADDR               =       #{HPGE_URL_ADDR}

	    ,   BBSCTT_CN                   =       #{BBSCTT_CN}
        ,   SXDC_SE_CD                  =       #{SXDC_SE_CD}
        ,   ACBG_SE_CD                  =       #{ACBG_SE_CD}
        ,   GRADE_SE_CD                 =       #{GRADE_SE_CD}
        ,   GRDTN_STTS_SE_CD            =       #{GRDTN_STTS_SE_CD}
        ,   REAL_CONSTT_SE_CD           =       #{REAL_CONSTT_SE_CD}
        ,   REAL_CONSTT_ETC_CN          =       #{REAL_CONSTT_ETC_CN}
        ,   YNGBGS_SE_NO                =       #{YNGBGS_SE_NO}
        ,   PROBM_STTS_LCLAS_SE_CD      =       #{PROBM_STTS_LCLAS_SE_CD}
        ,   PROBM_STTS_MLSFC_SE_CD      =       #{PROBM_STTS_MLSFC_SE_CD}
        ,   PROBM_STTS_SCLAS_SE_CD      =       #{PROBM_STTS_SCLAS_SE_CD}
        ,   PROBM_CAS_LCLAS_SE_CD       =       #{PROBM_CAS_LCLAS_SE_CD}
        ,   PROBM_CAS_SCLAS_SE_CD       =       #{PROBM_CAS_SCLAS_SE_CD}
        ,   ETC_CN                      =       #{ETC_CN}
        ,   LINK_PRCS_SE_CN             =       #{LINK_PRCS_SE_CN}
        ,   RCPT_RQST_COURS_SE_CD       =       #{RCPT_RQST_COURS_SE_CD}
        ,   LINK_INST_NM                =       #{LINK_INST_NM}
	    ,   LAST_MDFCN_DT               =       SYSDATE      
        ,   LAST_MDFR_ID                =       #{LAST_MDFR_ID}    
    WHERE   1=1
	AND     BBSCTT_ESNTAL_NO            =       #{BBSCTT_ESNTAL_NO}
	AND     BBSCTT_TYPE_SE_CD           =       #{BBSCTT_TYPE_SE_CD}                    /*  게시판유형구분코드  */

mapper.insert:
/* * isry.couns.constt.bbsnav.mapper.BbsnavListMapper.insertRespod : 기타상담게시판 답글(AYE120) 등록 * 2023.04.17 수정 : 불필요한 컬럼 삭제 - Jeong.Won.Je */
SELECT AYE120_SQ01.CURRVAL FROM DUAL
INSERT INTO AYE120 ( RETE_ESNTAL_NO /* 답글고유번호 */ , BBSCTT_ESNTAL_NO /* 게시글고유번호 */ , BBSCTT_TYPE_SE_CD /* 게시글유형구분 */ , RETE_CN /* 답글내용 */ , FRST_RGTR_ID , FRST_REG_DT , LAST_MDFR_ID , LAST_MDFCN_DT ) VALUES( AYE120_SQ01.NEXTVAL , #{BBSCTT_ESNTAL_NO} , #{BBSCTT_TYPE_SE_CD} , #{RETE_CN} , #{FRST_RGTR_ID} , SYSDATE , #{LAST_MDFR_ID} , SYSDATE )

mapper.update:
UPDATE  /* isry.couns.constt.bbsnav.mapper.BbsnavListMapper.RespodDtlCnt : 네이버게시판 답글조회수 */
        AYE120  
SET   
        RDCNT_NOCS = NVL(RDCNT_NOCS, 0) +1 
WHERE   1=1
    AND RETE_ESNTAL_NO      =   #{RETE_ESNTAL_NO}
    AND BBSCTT_ESNTAL_NO    =   #{BBSCTT_ESNTAL_NO}     
    AND BBSCTT_TYPE_SE_CD   =   #{BBSCTT_TYPE_SE_CD}

UPDATE  /* isry.couns.constt.bbsnav.mapper.BbsnavListMapper.insertCrisis : 네이버게시판 위기유형등록 */
        AYE100  
SET
        CRISIS_TYPE_SE_CD      =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}                    /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.bbsnav.mapper.BbsnavListMapper.updateCrisisBoard : 네이버게시판 위기유형등록 */
        AYA110  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}                    /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.bbsnav.mapper.BbsnavListMapper.updateCrisisPerson : 네이버게시판 위기유형등록 */
        AYA120  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   CLIENA_ID               =       #{CLIENA_ID}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       #{BBSCTT_TYPE_SE_CD}                    /*  게시판유형구분코드  */

    /* 
     * isry.couns.constt.bbsnav.mapper.BbsnavListMapper.updateReteDlivCmptn : 기타상담게시판 - 카카오톡 오픈채팅 : 내담자에게 답글전달 확인 여부 UPDATE
     * 2023.05.10 : 추가 - Jeong.Won.Je
     */
		UPDATE  AYE100
		SET     RETE_DLIV_CMPTN_YN  =   #{RETE_DLIV_CMPTN_YN}
		        , LAST_MDFR_ID      =   #{loginId}
		        , LAST_MDFCN_DT     =   SYSDATE
		WHERE   1=1
		AND     BBSCTT_ESNTAL_NO    =   #{BBSCTT_ESNTAL_NO}
		AND     BBSCTT_TYPE_SE_CD   =   #{BBSCTT_TYPE_SE_CD}
